"""Aggregate actual same-input runs without dropping the first comparison attempt."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parent
cases=[]
for label in ('reference_baseline8','fine101_path'):
    pointer=json.loads((ROOT/(label+'_LATEST.json')).read_text());path=ROOT/pointer['path'];report=json.loads(path.read_text());rows=[r for r in report['rows'] if r['status']=='PASS_NUMERICAL_SAME_INPUT']
    maxima={key:max(r[key] for r in rows) for key in ('coefficient_max_abs_discrepancy','matrix32_same_coordinate_discrepancy','matrix18_direct_overlap_discrepancy','phase_count_max_abs_discrepancy','energy_eV_common_constant_discrepancy')}
    changes=[{'left_t':a['k_fractional'][0],'right_t':b['k_fractional'][0],'left_counts':a['irrep_nearest_integer_counts'],'right_counts':b['irrep_nearest_integer_counts']} for a,b in zip(rows,rows[1:]) if a['irrep_nearest_integer_counts']!=b['irrep_nearest_integer_counts']]
    cases.append({'id':label,'status':report['status'],'record_path':pointer['path'],'record_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'QE_version':report['source_qe_version'],'input_kpoints':len(report['rows']),'actual_C4_little_group_calls':report['actual_irrep_C4_calls'],'points_outside_C4_little_group':sum(r['status']=='NOT_C4Z_LITTLE_GROUP_POINT' for r in report['rows']),'input_files_unchanged':report['input_files_unchanged'],'maxima':maxima,'all_nearest_counts_match':all(r['irrep_nearest_integer_counts']==r['raw_nearest_integer_counts'] for r in rows),'all_prefixes_numerically_resolved':all(r['raw_band18_prefix_status']=='ASSIGNED_NUMERICALLY' for r in rows),'first_last_counts':[rows[0]['irrep_nearest_integer_counts'],rows[-1]['irrep_nearest_integer_counts']],'count_change_brackets':changes if label=='fine101_path' else [],'dependencies':report['dependencies']})
attempts=[]
for path in sorted((ROOT/'runs').glob('*/RESULTS.json')):
    r=json.loads(path.read_text());attempts.append({'record_path':path.relative_to(ROOT).as_posix(),'record_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'status':r['status'],'reason_if_initial_mismatch':'Initial comparator compared coordinate G^-1 B directly with overlap B and used two different published Hartree-to-eV constants. Retained raw arrays reproduce those differences; corrected comparison changes semantics, not tolerances.' if r['status']=='MISMATCH' else None})
summary={'schema':'same-input-external-IrRep-C4-summary-v1','status':'PASS_NUMERICAL_SAME_INPUT' if all(c['status']=='PASS_NUMERICAL_SAME_INPUT' for c in cases) else 'FAIL','cases':cases,'retained_attempts':attempts,'exactness':'Floating-point same-input comparison, not an exact interval certificate.','tool_scope':'Actual IrRep matrix computation and binary parsing; four-root decomposition by this adapter. No external global gluing or across-path target test.','shared_conventions':'Same XML/raw spinors, +pi/2 Cartesian z rotation, documented SU(2) lift, root order [7,1,3,5]. No wavefunction fit, polar repair, fitted energy shift or matrix cutoff.'}
(ROOT/'SUMMARY.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8');print(json.dumps({'status':summary['status'],'actual_C4_calls':sum(c['actual_C4_little_group_calls'] for c in cases),'retained_attempts':len(attempts)}))
